export const SAMPLE_TIMES=['09:00','10:30','12:00','14:00','15:30','17:00'];
export function zonedParts(value,zone){const values={};new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(value).forEach(p=>{if(p.type!=='literal')values[p.type]=p.value});return values}
export function dateKey(value,zone){const p=zonedParts(value,zone);return `${p.year}-${p.month}-${p.day}`}
export function toUTC(date,time,zone){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^\d{2}:\d{2}$/.test(time))throw Error('Choose a valid date and time.');const [y,m,d]=date.split('-').map(Number),[h,n]=time.split(':').map(Number);if(h>23||n>59)throw Error('Invalid time.');const desired=Date.UTC(y,m-1,d,h,n);let candidate=desired;for(let i=0;i<4;i++){const p=zonedParts(new Date(candidate),zone);const observed=Date.UTC(Number(p.year),Number(p.month)-1,Number(p.day),Number(p.hour),Number(p.minute),Number(p.second));const next=candidate+desired-observed;if(next===candidate)break;candidate=next}const result=new Date(candidate),p=zonedParts(result,zone);if(`${p.year}-${p.month}-${p.day}`!==date||`${p.hour}:${p.minute}`!==time)throw Error('This local time is not available. Choose another time.');return result}
export function formatDate(date){return new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'))}
export function validDetails(data,platform){const errors={};if(!data.name.trim())errors.name='Please enter your name.';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email.trim()))errors.email='Please enter a valid email address.';if(platform==='whatsapp'&&!/^\+[1-9]\d{7,14}$/.test(data.phone.replace(/[\s().-]/g,'')))errors.phone='Enter your WhatsApp number with + and country code.';return errors}
function escapeICS(v){return String(v).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,')}
function fold(line){let out='',chunk='',size=0;for(const ch of line){const len=new TextEncoder().encode(ch).length;if(size+len>73){out+=chunk+'\r\n ';chunk='';size=1}chunk+=ch;size+=len}return out+chunk}
export function calendarDraft({date,time,zone,platform,callType,focus,uid},now=new Date()){const start=toUTC(date,time,zone),end=new Date(start.getTime()+30*60000);const stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');const method=platform==='whatsapp'?`WhatsApp ${callType==='video'?'video':'voice'} call`:platform==='teams'?'Microsoft Teams':'Zoom';return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//WORKX IT//Scheduling Preview//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','BEGIN:VEVENT','UID:'+escapeICS(uid),'DTSTAMP:'+stamp(now),'DTSTART:'+stamp(start),'DTEND:'+stamp(end),'SUMMARY:'+escapeICS('[PREVIEW — NOT BOOKED] WorkX IT · '+method),'DESCRIPTION:'+escapeICS('Scheduling preview only. No appointment is booked and no invitation has been sent.\nFocus: '+focus+'\nSelected timezone: '+zone+'\nPlatform preference: '+method+'\nConfirm a real meeting with WorkX IT before attending.'),'STATUS:TENTATIVE','TRANSP:TRANSPARENT','END:VEVENT','END:VCALENDAR'].map(fold).join('\r\n')+'\r\n'}
